$u=current_user();
if(!$u || !(has_permission('settings.manage',$u)||has_permission('tenants.manage',$u)||has_permission('businesses.manage',$u))){http_response_code(403);exit('Forbidden');}
$allowedTabs=['overview','officers','sync','sections','facts','sources'];
$tab=(string)($_GET['tab']??$_POST['return_tab']??'overview');if(!in_array($tab,$allowedTabs,true))$tab='overview';
$msg='';$err='';$syncResult=null;
try{
    if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
        csrf_check();$a=(string)($_POST['action']??'');
        if($a==='settings'){
            sk1240_save_settings($_POST,(int)($u['id']??0));sk1251_save_settings($_POST,(int)($u['id']??0));sk1260_save_settings($_POST,(int)($u['id']??0));$msg='City portal settings saved.';
        }elseif($a==='smart_settings'){
            sk1260_save_settings($_POST,(int)($u['id']??0));$msg='Smart city settings saved.';
        }elseif($a==='item'){sk1240_save_item($_POST);$msg='City fact updated.';
        }elseif($a==='section'){sk1240_save_section($_POST);$msg='Section settings saved.';
        }elseif($a==='media_upload'){sk1251_save_media($_POST,$_FILES);$msg='Image uploaded.';
        }elseif($a==='media_delete'){sk1251_delete_media((int)($_POST['id']??0));$msg='Image removed.';
        }elseif($a==='role_save'){sk1261_save_role_profile($_POST,$_FILES,(int)($u['id']??0));$msg='Administration officer profile saved.';
        }elseif($a==='officer_sort'){sk1261_save_role_orders((array)($_POST['role_order']??[]));$msg='Public officer card order saved.';
        }elseif($a==='officer_save'){sk1251_save_officer($_POST,$_FILES,(int)($u['id']??0));$msg='Additional officer profile saved.';
        }elseif($a==='officer_delete'){sk1251_delete_officer((int)($_POST['id']??0));$msg='Officer profile removed.';
        }elseif($a==='sync_now'){$syncResult=sk1260_sync_all('manual',(int)($u['id']??0));$msg='Official-source sync finished: '.$syncResult['checked'].' checked, '.$syncResult['changed'].' updated, '.$syncResult['failed'].' failed.';}
    }
}catch(Throwable $e){$err=$e->getMessage();}

$s=sk1240_settings();$p=sk1251_settings();$smart=sk1260_settings();$sections=sk1240_sections(true);$items=sk1240_items(true);$sources=sk1240_sources(true);$media=sk1251_media_map();$officers=sk1251_officers(true);$roles=sk1260_roles();$runs=sk1260_sync_runs();
$roleOfficerIds=[];foreach($roles as $r){if(!empty($r['officer_id']))$roleOfficerIds[(int)$r['officer_id']]=1;}
$otherOfficers=array_values(array_filter($officers,fn($o)=>empty($roleOfficerIds[(int)$o['id']])));
$enabled=count(array_filter($items,fn($x)=>!empty($x['enabled'])));$featured=count(array_filter($items,fn($x)=>!empty($x['featured'])));
function sk1260_admin_tab(string $key,string $label,string $active): string {return '<a class="'.($key===$active?'active':'').'" href="?tab='.rawurlencode($key).'">'.sk1260_h($label).'</a>';}
function sk1260_status_class(string $s): string {return in_array($s,['verified','updated','seeded','ok'],true)?'good':(in_array($s,['failed','warning'],true)?'bad':'warn');}
page_start('City Content Studio',true);
